'use server'

import { updateTag } from 'next/cache'
import { redirect } from 'next/navigation'
import { insertPost } from '@/lib/posts'

export async function createPost(formData: FormData): Promise<void> {
  const title = formData.get('title')
  const content = formData.get('content')

  if (typeof title !== 'string' || !title.trim()) {
    throw new Error('A post title is required.')
  }
  if (typeof content !== 'string' || !content.trim()) {
    throw new Error('Post content is required.')
  }

  await insertPost(title.trim(), content.trim())

  // Expire the tagged value immediately. The next read waits for fresh data.
  updateTag('posts')
  redirect('/')
}
import { randomUUID } from 'node:crypto'
import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { cacheTag } from 'next/cache'

export type Post = {
  id: string
  title: string
  content: string
  createdAt: string
}

// Local storage for this starter app. Replace this with a database for deployment.
const postsFile = join(process.cwd(), '.data', 'posts.json')

async function readPosts(): Promise<Post[]> {
  try {
    return JSON.parse(await readFile(postsFile, 'utf8')) as Post[]
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return []
    throw error
  }
}

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return readPosts()
}

// Serialize writes so two submissions cannot overwrite one another.
let pendingWrite: Promise<void> = Promise.resolve()

export async function insertPost(title: string, content: string): Promise<void> {
  const write = pendingWrite.then(async () => {
    const post: Post = {
      id: randomUUID(),
      title,
      content,
      createdAt: new Date().toISOString(),
    }
    const posts = await readPosts()
    await mkdir(dirname(postsFile), { recursive: true })
    const tempFile = `${postsFile}.${post.id}.tmp`
    await writeFile(tempFile, JSON.stringify([post, ...posts], null, 2))
    await rename(tempFile, postsFile)
  })

  pendingWrite = write.catch(() => {})
  await write
}
